package com.fileservice.core

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

enum class Role { ADMIN, EDITOR, VIEWER }

data class User(val id: String, val role: Role)

data class FileHandle(
    val id: String,
    val path: String,
    var content: ByteArray?,
    var refCount: Int = 1,
    var released: Boolean = false
) {
    fun acquire(): FileHandle {
        refCount++
        return this
    }

    fun release() {
        refCount--
        if (refCount <= 0) {
            content = null
            released = true
        }
    }
}

class FileCache {
    private val cache = ConcurrentHashMap<String, FileHandle>()
    private val lock = ReentrantReadWriteLock()

    fun getOrLoad(fileId: String, loader: () -> ByteArray): FileHandle {
        return lock.read {
            cache[fileId]?.acquire()
        } ?: lock.write {
            cache[fileId]?.acquire() ?: run {
                val handle = FileHandle(fileId, "/data/$fileId", loader())
                cache[fileId] = handle
                handle
            }
        }
    }

    fun evict(fileId: String) {
        lock.write {
            cache.remove(fileId)?.release()
        }
    }

    fun evictAll() {
        lock.write {
            cache.values.forEach { it.release() }
            cache.clear()
        }
    }
}

class AccessController {
    private val permissions = mapOf(
        Role.ADMIN to setOf("read", "write", "delete", "evict"),
        Role.EDITOR to setOf("read", "write"),
        Role.VIEWER to setOf("read")
    )

    fun checkPermission(user: User, action: String): Boolean {
        return permissions[user.role]?.contains(action) == true
    }
}

class FileProcessingService {
    private val cache = FileCache()
    private val accessController = AccessController()
    private val processingResults = ConcurrentHashMap<String, ByteArray>()

    // Validate fileId to prevent path traversal (CWE-22).
    // Only allow simple, safe identifiers with no path separators or traversal sequences.
    private val safeFileIdRegex = Regex("^[A-Za-z0-9._-]+$")

    private fun validateFileId(fileId: String): Boolean {
        if (fileId.isBlank()) return false
        if (fileId.contains("..")) return false
        if (fileId.contains('/') || fileId.contains('\\')) return false
        return safeFileIdRegex.matches(fileId)
    }

    fun processFile(user: User, fileId: String): Result<ByteArray> {
        if (!accessController.checkPermission(user, "read")) {
            return Result.failure(SecurityException("Access denied"))
        }

        if (!validateFileId(fileId)) {
            return Result.failure(IllegalArgumentException("Invalid file id"))
        }

        val handle = cache.getOrLoad(fileId) {
            loadFromDisk(fileId)
        }

        val transformed = transform(handle)
        handle.release()

        // Store a defensive copy of the result, not the handle
        processingResults["${user.id}:$fileId"] = transformed

        return Result.success(transformed)
    }

    fun evictFile(user: User, fileId: String): Result<Unit> {
        if (!accessController.checkPermission(user, "evict")) {
            return Result.failure(SecurityException("Access denied"))
        }

        if (!validateFileId(fileId)) {
            return Result.failure(IllegalArgumentException("Invalid file id"))
        }

        cache.evict(fileId)
        return Result.success(Unit)
    }

    fun getProcessingResult(user: User, fileId: String): Result<ByteArray> {
        if (!accessController.checkPermission(user, "read")) {
            return Result.failure(SecurityException("Access denied"))
        }

        if (!validateFileId(fileId)) {
            return Result.failure(IllegalArgumentException("Invalid file id"))
        }

        val key = "${user.id}:$fileId"
        val result = processingResults[key]
            ?: return Result.failure(NoSuchElementException("No result found"))

        // Return a defensive copy of the stored result
        return Result.success(result.copyOf())
    }

    private fun transform(handle: FileHandle): ByteArray {
        if (handle.released) {
            throw IllegalStateException("Cannot transform released handle")
        }
        val data = handle.content
            ?: throw IllegalStateException("Handle content is null")
        return data.map { (it.toInt() xor 0x42).toByte() }.toByteArray()
    }

    fun cleanupUserResults(user: User) {
        val keysToRemove = processingResults.keys.filter { it.startsWith("${user.id}:") }
        keysToRemove.forEach { key ->
            processingResults.remove(key)
        }
    }

    private fun loadFromDisk(fileId: String): ByteArray {
        // Simulated disk load
        return "FILE_CONTENT_$fileId".toByteArray()
    }
}

fun main() {
    val service = FileProcessingService()
    val admin = User("admin1", Role.ADMIN)
    val viewer = User("viewer1", Role.VIEWER)

    // Viewer processes a file
    service.processFile(viewer, "secret.dat")

    // Admin evicts the file from cache (releases the handle)
    service.evictFile(admin, "secret.dat")

    // Viewer retrieves processing result - safe, uses stored copy
    val result = service.getProcessingResult(viewer, "secret.dat")
    println("Result: ${result.getOrNull()?.size ?: "error"}")
}
